"""The conformance workflow the resolver renders, in both forms.

`EXPECTED_WORKFLOW` is the platform's own tree's form and `EXPECTED_LOCKED_WORKFLOW` the form
every other tree gets. Shared by `test_resolve_project.py` and
`test_resolve_conformance_workflow.py`; the text is pinned here rather than computed, so a
render that drifts fails both.
"""

PLATFORM_MARKER = "home/common/agent-skills/platform-manifest.json"
EXPECTED_LOCKED_WORKFLOW = """\
# Generated by resolve-project (project schema 2). Do not edit: the
# Conformance check fails while this file differs from what resolve-project renders.
name: Conformance

on:
  pull_request:
    branches:
      - "main"
  push:
    branches:
      - "main"

permissions:
  contents: read

jobs:
  conformance:
    name: Conformance
    runs-on: ubuntu-24.04
    timeout-minutes: 30
    steps:
      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          ref: ${{ github.event.pull_request.head.sha || github.sha }}
      - name: Install Nix
        uses: DeterminateSystems/nix-installer-action@v4
      - name: Run conformance
        run: |
          platform=$(jq -er '.nodes[.nodes[.root].inputs["agent-platform"]].locked | select(.type == "github") | "github:\\(.owner)/\\(.repo)/\\(.rev)"' devenv.lock)
          nix shell "$platform#agent-platform" --command conformance run --purpose ci
"""
EXPECTED_WORKFLOW = """\
# Generated by resolve-project (project schema 2). Do not edit: the
# Conformance check fails while this file differs from what resolve-project renders.
name: Conformance

on:
  pull_request:
    branches:
      - "main"
  push:
    branches:
      - "main"

permissions:
  contents: read

jobs:
  conformance:
    name: Conformance
    runs-on: ubuntu-24.04
    timeout-minutes: 30
    steps:
      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          ref: ${{ github.event.pull_request.head.sha || github.sha }}
      - name: Install Nix
        uses: DeterminateSystems/nix-installer-action@v4
      - name: Run conformance
        run: nix shell .#agent-platform --command conformance run --purpose ci --lint-times
      - name: Read the contract with the base platform
        run: |
          base="git+file://$GITHUB_WORKSPACE?rev=${{ github.event.pull_request.base.sha || github.event.before }}"
          nix build "$base#agent-platform" --out-link "$RUNNER_TEMP/base-platform"
          "$RUNNER_TEMP/base-platform/bin/resolve-project" platform-status --repo-root . >"$RUNNER_TEMP/base-status.json" 2>"$RUNNER_TEMP/base-warnings.txt" || { cat "$RUNNER_TEMP/base-status.json"; exit 1; }
          sed 's/^/::warning::/' "$RUNNER_TEMP/base-warnings.txt"
          jq -e '.compatibility.compatible' "$RUNNER_TEMP/base-status.json"
"""
